step.instructions:
This step submits a TSO batch job to run the following RACDCERT commands for user ID ${instance-CERT_USERID}:
- LIST all certificates
- LISTRING(*) to list all keyrings
- CERTAUTH LIST for CA label: ${instance-CA_LABEL}
- LISTRING for keyring: ${instance-KEYRING_LABEL}
- LISTCHAIN for certificate: ${instance-CERT_LABEL}

template.inlineTemplate:
//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36
//FILEOUT  DD SYSOUT=*
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 RACDCERT ID(${instance-CERT_USERID}) LIST
 RACDCERT ID(${instance-CERT_USERID}) LISTRING(*)
 RACDCERT CERTAUTH LIST(LABEL('${instance-CA_LABEL}'))
 RACDCERT ID(${instance-CERT_USERID}) LISTRING(${instance-KEYRING_LABEL})
 RACDCERT ID(${instance-CERT_USERID}) LISTCHAIN(LABEL('${instance-CERT_LABEL}'))
/*
